/// <summary>
/// Extending <c>CustSumForPaym</c> for DD Automation.
/// </summary>
internal class METDDCustSumForPaym extends CustSumForPaym
{
    private boolean                         metFromAutomation;
    private container                       metPackedFileFormatParams;
    private LedgerJournalId                 metAutomationJournalId;
    private METCustPaymJournalAutomation    metCustPaymJournalAutomation;


}

Method.Source:
    /// <summary>
    /// set ledgerjournalId
    /// </summary>
    protected void updateQuery()
    {
        if(this.metFromAutomation && this.metAutomationJournalId)
        {
            // 'ledgerJournalId' is unpacked and overwritten with a blank value.
            // Ensure value is repopulated before query is updated.
            this.ledgerJournalId = this.metAutomationJournalId;
        }

        super();
    }

    /// <summary>
    /// Initialise <c>METCustVendPaymERExport</c>
    /// </summary>
    /// <param name = "_eRFormatMappingID">_eRFormatMappingID</param>
    /// <returns>CustVendPaymERExport</returns>
    protected CustVendPaymERExport initERPaymentExport(ERFormatMappingID _eRFormatMappingID)
    {
        var custVendPaymERExport = new METCustVendPaymERExport();
        custVendPaymERExport.parmERBinding(_eRFormatMappingID);
        custVendPaymERExport.parmLedgerJournalId(ledgerJournalId);
        custVendPaymERExport.parmBankAccountID(bankAccountID);
        custVendPaymERExport.parmERFileName(erFileName);
        custVendPaymERExport.parmQuery(this.queryRun().query());
        custVendPaymERExport.parmShowParamsDialog(true);
        custVendPaymERExport.parmCustVendPaymModeTable(this.paymModeTable());

        custVendPaymERExport.metParmFromAutomation(this.metParmFromAutomation());
        
        return custVendPaymERExport;
    }

    /// <summary>
    /// Set Automation flag
    /// </summary>
    void initCustVendOutPaym()
    {
        super();
        custVendOutPaym.metParmFromAutomation(metFromAutomation);
      
        if(this is CustSumForPaym)
        {
            if(conLen(metPackedFileFormatParams))
            {
                custVendOutPaym.unpack(metPackedFileFormatParams);
            }
        }

    }

/// <summary>
/// Check Automation
/// </summary>
/// <returns>identifierName</returns>
public identifierName lastValueElementName()
{
    IdentifierName ret = super();
    if(this.metFromAutomation)
    {
        ret = '';
    }
    return ret;
}

/// <summary>
/// set and get automation journalId
/// </summary>
/// <param name = "_metAutomationJournalId">Journalid</param>
/// <returns>Journalid</returns>
public LedgerJournalId metParmAutomationJournalId(LedgerJournalId _metAutomationJournalId = metAutomationJournalId)
{
    metAutomationJournalId = _metAutomationJournalId;
    return metAutomationJournalId;
}

/// <summary>
/// set and get params
/// </summary>
/// <param name = "_metPackedFileFormatParams">container</param>
/// <returns>container for file format parameters</returns>
public container metParmPackedFileFormatParams(container _metPackedFileFormatParams = metPackedFileFormatParams)
{
    metPackedFileFormatParams = _metPackedFileFormatParams;
    return metPackedFileFormatParams;
}

/// <summary>
/// parmfromAutomation
/// </summary>
/// <param name = "_metFromAutomation">_metFromAutomation</param>
/// <returns>fromAutomation</returns>
public boolean metParmFromAutomation(boolean _metFromAutomation = metFromAutomation)
{
    metFromAutomation = _metFromAutomation;
    return metFromAutomation;
}

/// <summary>
/// metParmCustPaymJournalAutomation
/// </summary>
/// <param name = "_metCustPaymJournalAutomation">_metCustPaymJournalAutomation</param>
/// <returns>metCustPaymJournalAutomation</returns>
public METCustPaymJournalAutomation metParmCustPaymJournalAutomation(METCustPaymJournalAutomation _metCustPaymJournalAutomation = metCustPaymJournalAutomation)
{
    metCustPaymJournalAutomation = _metCustPaymJournalAutomation;
    return metCustPaymJournalAutomation;
}
